/* A4 invoices generated from authorized order snapshots, independent of viewport. */
(function(){
 'use strict';
 let ready;
 const script=src=>new Promise((resolve,reject)=>{const el=document.createElement('script');el.src=src;el.onload=resolve;el.onerror=()=>{el.remove();reject(Error('PDF tools could not load. Please retry.'))};document.head.append(el)});
 function load(){return ready||(ready=(async()=>{if(!window.pdfMake)await script('/vendor/pdfmake-0.3.14.min.js');await script('/vendor/pdfmake-fonts-0.3.14.js')})().catch(e=>{ready=null;throw e}))}
 const cash=n=>'PKR '+Number(n||0).toLocaleString('en-PK',{minimumFractionDigits:2,maximumFractionDigits:2});
 const str=x=>String(x??'');
 const green='#075C3C',grey='#61756B';
 const status=s=>({placed:'Pending',confirmed:'Accepted',processing:'Processing',shipped:'Dispatched',delivered:'Delivered',cancelled:'Cancelled',returned:'Returned'})[s]||str(s);
 async function imageData(url,maxSize=240){try{if(!/^(https:\/\/|\/)/.test(url||''))return null;const response=await fetch(url,{signal:AbortSignal.timeout(6000)});if(!response.ok)return null;const blob=await response.blob();if(!/^image\/(png|jpeg|webp)/.test(blob.type))return null;const bitmap=await createImageBitmap(blob),canvas=document.createElement('canvas');const scale=Math.min(1,maxSize/Math.max(bitmap.width,bitmap.height));canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();return canvas.toDataURL('image/jpeg',0.95)}catch{return null}}
 function definition(o,shipments,assets={}){
  const sections=shipments.map((s,index)=>{
   const selected=s?[s]:o.shipments||[],items=selected.flatMap(window.MioFulfillment.invoiceItems),sum=key=>selected.reduce((n,v)=>n+Number(v[key]||0),0),total=s?Number(s.total_pkr):Number(o.total_pkr),paid=s?Number(s.paid_pkr):Number(o.funding.paid_pkr),closed=['cancelled','returned'].includes(o.status),due=closed?0:Math.max(0,Math.round((total-paid)*100)/100),code=s?.shipment_code||o.order_code,number=s?.invoice_number||'INV-'+o.order_code;
   const barcode=document.createElementNS('http://www.w3.org/2000/svg','svg');window.JsBarcode(barcode,code,{format:'CODE128',width:2,height:46,margin:12,displayValue:false});
   const meta=rows=>({layout:'noBorders',table:{widths:[85,'*'],body:rows.map(([label,value])=>[{text:label,color:grey,fontSize:8},{text:str(value),bold:true,fontSize:9}])}});
   const address=title=>({stack:[{text:title,style:'section'}, {text:str(o.shipping_name),bold:true,margin:[0,6,0,3]}, {text:str(o.shipping_address),fontSize:9},{text:str(o.shipping_city)+' · '+str(o.shipping_phone),fontSize:9,margin:[0,3,0,0]}]});
   const rows=items.map((i,n)=>[{text:str(n+1),color:grey},{stack:[...(assets[i.image_url]?[{image:assets[i.image_url],fit:[36,36],margin:[0,0,0,4]}]:[]),{text:str(i.name),bold:true},...(i.bundle?[{text:str(i.bundle),fontSize:7,color:grey}]:[])]} ,str(i.sku||'—'),{text:str(i.quantity),alignment:'center'},{text:cash(i.unit_price),alignment:'right'},{text:cash(Number(i.unit_price)*Number(i.quantity)),alignment:'right'}]);
   const totals=[['Subtotal',sum('gross_pkr')],['Discount',-sum('discount_pkr')],['Delivery',sum('delivery_pkr')],['GRAND TOTAL',total],['Payments received',paid],...(o.funding.payment_state==='refund_due'?[['Refund pending',paid]]:[]),['Remaining to collect',due]].map(([name,value])=>[{text:name,bold:true,fillColor:name==='GRAND TOTAL'?green:null,color:name==='GRAND TOTAL'?'#fff':green},{text:cash(value),alignment:'right',bold:true,fillColor:name==='GRAND TOTAL'?green:null,color:name==='GRAND TOTAL'?'#fff':green}]);
   return {pageBreak:index?'before':undefined,stack:[
    {columns:[assets.logo?{image:assets.logo,width:225}:{text:'MARKET IS ONLINE',fontSize:21,bold:true,color:green},{stack:[{text:'ORDER INVOICE',fontSize:21,bold:true,color:green,alignment:'right'},{text:s?'Vendor shipment':'Order summary',fontSize:9,color:grey,alignment:'right',margin:[0,5,0,0]}]}]},
    {text:'E-Commerce & Network Marketing Platform',fontSize:8,color:grey,margin:[0,6,0,12]},
    {canvas:[{type:'line',x1:0,y1:0,x2:454,y2:0,lineWidth:3,lineColor:green},{type:'line',x1:454,y1:0,x2:523,y2:0,lineWidth:3,lineColor:'#EEA014'}],margin:[0,0,0,16]},
    {columns:[meta([['Order number',o.order_code],['Invoice number',number],['Order date',new Date(o.created_at).toLocaleDateString('en-GB',{timeZone:'Asia/Karachi'})],...(s?[['Shipment',code]]:[])]),meta([['Payment method',Number(o.shopping_points_used)>0?'Shopping Points + COD':o.payment_method==='COD'?'Cash on Delivery':str(o.payment_method||'Advance')],['Payment status',o.funding.payment_state==='refund_due'?'Refund pending':o.funding.payment_state==='refunded'?'Refunded':paid>=total?'Paid':paid>0?'Part paid':'Unpaid'],['Order status',status(o.status)],['Delivery status',status(s?.status||o.status)]])],columnGap:18,margin:[0,0,0,16]},
    {columns:[address('BILLING ADDRESS'),address('SHIPPING ADDRESS')],columnGap:24,margin:[0,0,0,16]},
    {table:{widths:[100,'*'],body:[[{text:'SELLER INFORMATION',bold:true,color:green},{stack:selected.flatMap(v=>[{text:str(v.vendor_snapshot.name),bold:true},{text:str(v.vendor_snapshot.country||'Pakistan')+(v.vendor_snapshot.phone?' · '+v.vendor_snapshot.phone:''),fontSize:8,color:grey}])}]]},layout:{fillColor:()=>'#EFF5F1',hLineWidth:()=>0,vLineWidth:()=>0,paddingTop:()=>10,paddingBottom:()=>10,paddingLeft:()=>10,paddingRight:()=>10},margin:[0,0,0,16]},
    {table:{headerRows:1,dontBreakRows:true,widths:[16,'*',55,22,75,75],body:[['#','Product','SKU','Qty','Unit price','Total'].map(text=>({text,bold:true,color:'#fff',fillColor:green})),...rows]},layout:{hLineColor:()=>'#D7E2DA',vLineWidth:()=>0,hLineWidth:()=>.5,paddingTop:()=>9,paddingBottom:()=>9,paddingLeft:()=>6,paddingRight:()=>6},fontSize:8,margin:[0,0,0,16]},
    {unbreakable:true,stack:[{columns:[{width:'*',text:'PPV eligibility follows delivery and confirmed payment. Sponsor/MIO holds are security and do not reduce the amount payable.',fontSize:8,color:grey,lineHeight:1.4},{width:264,table:{widths:['*',100],body:totals},layout:{hLineWidth:()=>.5,vLineWidth:()=>0,hLineColor:()=>'#D7E2DA',paddingTop:()=>7,paddingBottom:()=>7,paddingLeft:()=>8,paddingRight:()=>8},fontSize:9}],columnGap:20},
    {canvas:[{type:'line',x1:0,y1:0,x2:523,y2:0,lineWidth:.7,lineColor:'#B1C7B9'}],margin:[0,20,0,14]},
    {columns:[{width:92,stack:[{qr:location.origin+location.pathname+'#order/'+o.id,fit:78},{text:'Secure order details',fontSize:7,color:grey,margin:[0,5,0,0]}]},{width:'*',stack:[{svg:barcode.outerHTML,fit:[285,58],alignment:'center'},{text:code,alignment:'center',fontSize:9,margin:[0,5,0,0]}]},{width:100,text:'Thank you for shopping with us.',color:green,bold:true,fontSize:11,margin:[0,14,0,0]}],columnGap:12}]}]};
  });
  return {pageSize:'A4',pageOrientation:'portrait',pageMargins:[36,32,36,36],info:{title:'Invoice '+o.order_code,author:'Market is Online'},defaultStyle:{font:'Roboto',fontSize:10,color:'#223F30'},styles:{section:{fontSize:10,bold:true,color:green}},content:sections,footer:(current,count)=>({columns:[{text:'Market is Online · '+o.order_code,color:grey},{text:current+' / '+count,alignment:'right',color:grey}],fontSize:8,margin:[36,12,36,0]})};
 }
 async function download(o,shipmentId=null,all=false){await load();const chosen=shipmentId?o.shipments.find(s=>s.id===shipmentId):null;if(shipmentId&&!chosen)throw Error('Vendor slip is unavailable. Refresh the order.');const shipments=all?o.shipments:[chosen];if(!shipments.length)throw Error('No vendor slips are available yet.');const urls=[...new Set(shipments.flatMap(s=>(s?[s]:o.shipments).flatMap(window.MioFulfillment.invoiceItems).map(i=>i.image_url).filter(Boolean)))];const assets={};await Promise.all(urls.map(async url=>{const data=await imageData(url);if(data)assets[url]=data}));assets.logo=await imageData('/market-is-online-logo.png',900);const file=(chosen?.invoice_number||(all?'Vendor-slips-':'Invoice-')+o.order_code).replace(/[^a-z0-9_-]/gi,'-')+'.pdf';await window.pdfMake.createPdf(definition(o,shipments,assets)).download(file);}
 window.MioInvoicePDF={definition,download};
})();
